#!/usr/bin/env python3
"""__DISPLAY_NAME__ — generated by `plexi app init`.

This scaffold demonstrates every major SDK interaction pattern. Use it as a
reference, then delete what you don't need.

Interactions covered:
  - Keyboard navigation (j/k, arrows, h/l for tabs)
  - Mouse click on list items
  - Text input (add items via Enter)
  - Tabs with left/right switching
  - Notifications (fire-and-forget + choice)
  - State persistence (save/load across sessions)
  - Clipboard copy
  - Timers (auto-incrementing counter)
  - Command palette (on_command)
  - Paste handling (paste lines to add items)
  - Contextual escape (return to list tab vs close app)
  - ScrollLog for event tracing
  - InfoTable, FormField, ButtonRow, Section, Divider
"""
from plexi_sdk import App, RenderContext
from plexi_sdk.ui import (
    AppBar, ButtonRow, Card, Column, Divider, FooterKeys, FormField,
    InfoTable, Label, ScrollLog, Section, SelectList, Spacer,
)

PRIORITY_NORMAL = 50


class __CLASS_NAME__(App):
    # ── Setup ─────────────────────────────────────────────────────────

    async def on_init(self, ctx: RenderContext) -> None:
        state = ctx.load_state()

        self._tab = 0
        self._tab_names = ["List", "Form", "Info"]

        # Tab 0: List
        self._items: list[str] = state.get("items", ["First item", "Second item", "Third item"])
        self._list = SelectList(
            items=[{"name": it} for it in self._items],
            selected_idx=0,
        )

        # Tab 1: Form
        self._input = FormField("add_item", label="New item", placeholder="Type and press Enter")
        self._add_btn = ButtonRow("add_btn", "Add Item")
        self._notifications_on = True

        # Tab 2: Info
        self._counter: int = state.get("counter", 0)
        self._timer_running = False

        # Event log (newest last, ScrollLog reverses for display)
        self._events: list[str] = []

        self.emit.info("__DISPLAY_NAME__ initialized")

    # ── Render ────────────────────────────────────────────────────────

    def on_render(self, ctx: RenderContext) -> None:
        tab = self._tab
        tab_indicator = "  ".join(
            f"[{n}]" if i == tab else f" {n} "
            for i, n in enumerate(self._tab_names)
        )

        children: list = [
            AppBar(title="__DISPLAY_NAME__", subtitle=tab_indicator),
        ]

        if tab == 0:
            children += self._render_list_tab()
        elif tab == 1:
            children += self._render_form_tab(ctx)
        elif tab == 2:
            children += self._render_info_tab()

        children += [
            Divider(),
            Section("Event Log"),
            ScrollLog(self._events, max_pixel_height=80),
            self._footer(),
        ]

        ctx.render(Column(children))

    def _render_list_tab(self) -> list:
        count = len(self._items)
        selected = self._items[self._list.selected_idx] if self._items else "nothing"
        return [
            Section("Items"),
            self._list,
            Card([Label(f"Selected: {selected}", bold=True)]),
            Label(f"{count} item{'s' if count != 1 else ''}", tone="caption"),
        ]

    def _render_form_tab(self, ctx: RenderContext) -> list:
        children: list = [
            Section("Add an Item"),
            self._input,
            self._add_btn,
            Spacer(8),
            Label(
                f"Notifications: {'on' if self._notifications_on else 'off'}  "
                "(press 'n' to toggle)",
                tone="hint",
            ),
        ]
        if self._add_btn.clicked:
            submitted = self._input.submitted
            if submitted and submitted.strip():
                self._add_item(ctx, submitted.strip())
        return children

    def _render_info_tab(self) -> list:
        return [
            Section("App Info"),
            InfoTable([
                ("items", str(len(self._items))),
                ("counter", str(self._counter)),
                ("timer", "running" if self._timer_running else "stopped"),
                ("tab", self._tab_names[self._tab]),
            ]),
            Spacer(12),
            Label(
                "Press 't' to start/stop the timer. "
                "Press 'c' to copy item list to clipboard.",
                tone="hint",
            ),
        ]

    def _footer(self) -> FooterKeys:
        shared = [("h/l", "tab"), ("esc", "close")]
        if self._tab == 0:
            return FooterKeys([("j/k", "navigate"), ("x", "delete"), ("click", "select")] + shared)
        if self._tab == 1:
            return FooterKeys([("Enter", "submit"), ("n", "notif toggle")] + shared)
        return FooterKeys([("t", "timer"), ("c", "copy")] + shared)

    # ── Keyboard ──────────────────────────────────────────────────────

    async def on_key(self, ctx: RenderContext, key: str, mods: dict) -> None:
        # Tab switching: h/l or left/right
        if key in ("l", "right"):
            self._tab = min(self._tab + 1, len(self._tab_names) - 1)
            self._log(f"tab -> {self._tab_names[self._tab]}")
            return
        if key in ("h", "left"):
            self._tab = max(self._tab - 1, 0)
            self._log(f"tab -> {self._tab_names[self._tab]}")
            return

        if self._tab == 0:
            self._handle_list_key(ctx, key)
        elif self._tab == 1:
            self._handle_form_key(key)
        elif self._tab == 2:
            self._handle_info_key(key)

    def _handle_list_key(self, ctx: RenderContext, key: str) -> None:
        if key in ("j", "k", "up", "down"):
            self._list.handle_key(key)
            self._log(f"select #{self._list.selected_idx}")
            return
        if key == "x" and self._items:
            removed = self._items.pop(self._list.selected_idx)
            self._rebuild_list()
            self._save(ctx)
            self._log(f"deleted '{removed}'")

    def _handle_form_key(self, key: str) -> None:
        if key == "n":
            self._notifications_on = not self._notifications_on
            self._log(f"notifications {'on' if self._notifications_on else 'off'}")

    def _handle_info_key(self, key: str) -> None:
        if key == "t":
            if self._timer_running:
                self.emit.cancel_timer("counter")
                self._timer_running = False
                self._log("timer stopped")
            else:
                self.emit.set_timer("counter", 1000)
                self._timer_running = True
                self._log("timer started")
        elif key == "c":
            text = "\n".join(self._items) if self._items else "(empty)"
            self.emit.copy_to_clipboard(text)
            self._log(f"copied {len(self._items)} items to clipboard")

    # ── Mouse ─────────────────────────────────────────────────────────

    async def on_click(self, _ctx: RenderContext, _x: float, y: float, _button: str) -> None:
        if self._tab == 0:
            idx = self._list.hit_index(y)
            if idx is not None:
                self._list.selected_idx = idx
                self._log(f"clicked item #{idx}: {self._items[idx]}")

    # ── Text Input ────────────────────────────────────────────────────

    async def on_text_submitted(self, ctx: RenderContext, id: str, text: str) -> None:
        if id == "add_item" and text.strip():
            self._add_item(ctx, text.strip())

    # ── Timers ────────────────────────────────────────────────────────

    async def on_timer(self, ctx: RenderContext, timer_id: str) -> None:
        if timer_id == "counter":
            self._counter += 1
            self._save(ctx)
            if self._timer_running:
                self.emit.set_timer("counter", 1000)

    # ── Command Palette ───────────────────────────────────────────────

    async def on_command(self, ctx: RenderContext, text: str) -> None:
        self._log(f"command: {text}")
        if text == "clear":
            self._items.clear()
            self._rebuild_list()
            self._save(ctx)
            self._log("items cleared via command")

    # ── Paste ─────────────────────────────────────────────────────────

    async def on_paste(self, ctx: RenderContext, text: str) -> None:
        lines = [line.strip() for line in text.strip().splitlines() if line.strip()]
        for line in lines:
            self._add_item(ctx, line)
        self._log(f"pasted {len(lines)} item(s)")

    # ── Escape ────────────────────────────────────────────────────────

    def on_escape(self, _ctx: RenderContext) -> bool:
        if self._tab != 0:
            self._tab = 0
            self._log("escape -> list tab")
            return True
        return False

    # ── Helpers ────────────────────────────────────────────────────────

    def _add_item(self, ctx: RenderContext, text: str) -> None:
        self._items.append(text)
        self._rebuild_list()
        self._save(ctx)
        self._log(f"added '{text}'")
        if self._notifications_on:
            self.emit.notify("Item added", PRIORITY_NORMAL, body=text)

    def _rebuild_list(self) -> None:
        idx = min(self._list.selected_idx, max(0, len(self._items) - 1))
        self._list = SelectList(
            items=[{"name": it} for it in self._items],
            selected_idx=idx,
        )

    def _save(self, ctx: RenderContext) -> None:
        ctx.save_state({"items": self._items, "counter": self._counter})

    def _log(self, msg: str) -> None:
        self._events.append(msg)
        if len(self._events) > 50:
            self._events = self._events[-50:]
        self.emit.info(msg)


__CLASS_NAME__().run()
